/* Generated from marvel.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='marvel'],
[data-ui-theme='marvel'] {
  color-scheme: light;
  --ui-background: oklch(0.98 0.01 25.23);
  --ui-foreground: oklch(0.23 0.08 24.25);
  --ui-card: oklch(0.95 0.02 24.79);
  --ui-card-foreground: oklch(0.18 0.01 29.18);
  --ui-popover: oklch(0.94 0.01 25.23);
  --ui-popover-foreground: oklch(0.22 0.01 29.09);
  --ui-primary: oklch(0.55 0.22 27.03);
  --ui-primary-foreground: oklch(0.98 0.01 100.72);
  --ui-secondary: oklch(0.52 0.14 247.51);
  --ui-secondary-foreground: oklch(0.98 0.01 100.72);
  --ui-muted: oklch(0.94 0.02 26.09);
  --ui-muted-foreground: oklch(0.45 0.02 18.12);
  --ui-accent: oklch(0.86 0.04 33.03);
  --ui-accent-foreground: oklch(0.18 0.01 29.18);
  --ui-destructive: oklch(0.56 0.23 29.23);
  --ui-destructive-foreground: oklch(0.98 0.01 100.72);
  --ui-border: oklch(0.9 0.03 25.3);
  --ui-input: oklch(0.80 0.01 25.22);
  --ui-ring: oklch(0.50 0.12 244.86);
  --ui-chart-1: oklch(0.58 0.23 27.06);
  --ui-chart-2: oklch(0.61 0.18 251.95);
  --ui-chart-3: oklch(0.72 0.15 83.96);
  --ui-chart-4: oklch(0.67 0.15 144.89);
  --ui-chart-5: oklch(0.75 0.15 304.74);
  --ui-sidebar: oklch(0.97 0 0);
  --ui-sidebar-foreground: oklch(0.20 0.01 18.05);
  --ui-sidebar-primary: oklch(0.52 0.14 247.51);
  --ui-sidebar-primary-foreground: oklch(0.98 0.01 100.72);
  --ui-sidebar-accent: oklch(0.69 0.14 79.64);
  --ui-sidebar-accent-foreground: oklch(0.20 0.01 18.05);
  --ui-sidebar-border: oklch(0.87 0.01 25.23);
  --ui-sidebar-ring: oklch(0.52 0.14 247.51);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Merriweather', ui-serif, serif;
  --ui-font-heading: 'Outfit', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Geist Mono', ui-monospace, monospace;
  --ui-shadow-control: 0px 1px 3px 0px oklch(0 0 0 / 0.01);
  --ui-shadow-panel:
    0px 1px 3px 0px oklch(0 0 0 / 0.01), 0px 4px 6px -1px oklch(0 0 0 / 0.01);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='marvel'].dark,
[data-ui-theme='marvel'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.1744 0.0088 31.22);
  --ui-foreground: oklch(0.95 0.01 25.23);
  --ui-card: oklch(0.2177 0.0067 34.3);
  --ui-card-foreground: oklch(0.95 0.01 25.23);
  --ui-popover: oklch(0.18 0.01 29.18);
  --ui-popover-foreground: oklch(0.95 0.01 25.23);
  --ui-primary: oklch(0.5502 0.22 27.03);
  --ui-primary-foreground: oklch(0.98 0.01 100.72);
  --ui-secondary: oklch(0.50 0.14 249.16);
  --ui-secondary-foreground: oklch(0.98 0.01 100.72);
  --ui-muted: oklch(0.20 0.01 18.05);
  --ui-muted-foreground: oklch(0.70 0.01 25.22);
  --ui-accent: oklch(0.59 0.12 78.11);
  --ui-accent-foreground: oklch(0.95 0.01 25.23);
  --ui-destructive: oklch(0.56 0.23 29.23);
  --ui-destructive-foreground: oklch(0.98 0.01 100.72);
  --ui-border: oklch(0.3235 0.0086 17.61);
  --ui-input: oklch(0.38 0.01 17.71);
  --ui-ring: oklch(0.49 0.14 250.75);
  --ui-chart-1: oklch(0.64 0.25 26.85);
  --ui-chart-2: oklch(0.66 0.19 250.17);
  --ui-chart-3: oklch(0.78 0.16 87.01);
  --ui-chart-4: oklch(0.68 0.15 144.94);
  --ui-chart-5: oklch(0.75 0.15 304.74);
  --ui-sidebar: oklch(0.14 0.01 33.25);
  --ui-sidebar-foreground: oklch(0.95 0.01 25.23);
  --ui-sidebar-primary: oklch(0.50 0.14 249.16);
  --ui-sidebar-primary-foreground: oklch(0.98 0.01 100.72);
  --ui-sidebar-accent: oklch(0.59 0.12 78.11);
  --ui-sidebar-accent-foreground: oklch(0.95 0.01 25.23);
  --ui-sidebar-border: oklch(0.32 0.01 27.45 / 30%);
  --ui-sidebar-ring: oklch(0.50 0.14 249.16);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Merriweather', ui-serif, serif;
  --ui-font-heading: 'Outfit', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Geist Mono', ui-monospace, monospace;
  --ui-shadow-control: 0px 1px 3px 0px oklch(0 0 0 / 0.01);
  --ui-shadow-panel:
    0px 1px 3px 0px oklch(0 0 0 / 0.01), 0px 4px 6px -1px oklch(0 0 0 / 0.01);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
